{
  "identity": {
    "name": "Idaho Roofing Contractors (Idaho Roofing Contractors LLC)",
    "location": "1565 Rolling Hills Dr, Meridian, Idaho 83642",
    "claims": [
      {
        "statement": "The business identifies its legal entity name in its Terms and Conditions as Idaho Roofing Contractors LLC.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/terms/",
        "quote": "Idaho Roofing Contractors LLC"
      },
      {
        "statement": "The company lists its physical address at 1565 Rolling Hills Dr, Meridian, Idaho 83642.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "1565 Rolling Hills Dr Meridian, Idaho 83642"
      },
      {
        "statement": "The company states it has operated as a local family-operated roofing business in Southwest Idaho since 2001.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "Since we first opened our doors in 2001, our local family-operated roof installation experts have been doing everything from repairing existing roofing"
      }
    ]
  },
  "industry": {
    "industry": "Residential and Commercial Roofing Contracting",
    "activities": [
      "Roof replacement",
      "Roof repair",
      "New construction roofing",
      "Commercial and flat roofing",
      "Storm damage restoration and inspection reports"
    ],
    "claims": [
      {
        "statement": "Idaho Roofing Contractors is a residential and commercial roofing company serving Southwest Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "Idaho Roofing Contractors is a professional residential and commercial roofing company serving communities throughout Southwest Idaho for 25+ years."
      },
      {
        "statement": "The company performs roof replacements, new roof installations, and storm damage restorations.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "We can handle roof replacements, new installations, storm damage restorations, and more."
      },
      {
        "statement": "The company performs residential flashing repairs as well as full commercial flat roofing projects.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/services/",
        "quote": "We work on everything from a single failed flashing joint to a full commercial flat roof"
      },
      {
        "statement": "The business operates exclusively in the roofing trade and does not offer HVAC, plumbing, or electrical contracting services.",
        "label": "inference",
        "sourceUrl": "https://www.idahoroofingcontractors.com/services/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.idahoroofingcontractors.com/",
    "claims": [
      {
        "statement": "The homepage highlights over 940 customer reviews with a 4.9 average rating.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "Over 940 reviews With A 4.9 Average"
      },
      {
        "statement": "The company states that it holds an A+ rating with the Better Business Bureau and is a member of the Boise Metro Chamber.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "Idaho Roofing Contractors holds an A+ rating with the Better Business Bureau. We’re also a member of the Boise Metro Chamber."
      },
      {
        "statement": "The company states it is an Owens Corning Platinum Preferred Contractor in the Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "We were the first Owens Corning Platinum Preferred Contractor in Idaho, and we are still the only business with that status in the Treasure Valley."
      },
      {
        "statement": "The FAQ page states that most residential roof replacements in the Boise area cost between $10,000 and $15,000.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/faq/",
        "quote": "Most residential roof replacements in the Boise area run between $10,000 and $15,000, depending on the size of your home"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company displays Idaho contractor license number RCE-5471 and states it is fully licensed and insured in Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/faq/",
        "quote": "Idaho Roofing Contractors is fully licensed and insured in the state of Idaho (License No. RCE-5471)."
      },
      {
        "statement": "The company states that it carries general liability and workers compensation coverage on every job under Idaho license RCE-5471.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/services/",
        "quote": "Idaho contractor license RCE-5471, with general liability and workers compensation coverage on every job."
      }
    ],
    "limitations": "Active license status, bonding details, and corporate registration standing were not independently verified against external state registries because research is restricted to the company's own public website."
  },
  "existingSoftware": [
    {
      "product": "Google Ads",
      "purpose": "Online advertising and remarketing",
      "evidence": {
        "statement": "The Privacy Policy states that Google is used as a third-party vendor to serve ads using cookies.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/privacy-policy/",
        "quote": "Google, as a third party vendor, uses cookies to serve ads."
      }
    },
    {
      "product": "AccuLynx (unconfirmed product name from host leads.acculynx.com)",
      "purpose": "Roofing CRM and lead capture integration",
      "evidence": {
        "statement": "The homepage and contact page reference the host leads.acculynx.com, which likely indicates the use of AccuLynx roofing software for lead intake and field-service management.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Roofle Roof Quote PRO (unconfirmed product name from script app.roofle.com)",
      "purpose": "Automated online roof quoting and lead capture widget",
      "evidence": {
        "statement": "The homepage loads https://app.roofle.com/roof-quote-pro-widget.js?id=undje-n1S331r6UN7AwBi, which likely provides an automated roof quote widget.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Birdeye and Trustindex (unconfirmed product names from script sources)",
      "purpose": "Customer review aggregation and display widgets",
      "evidence": {
        "statement": "The homepage loads https://cdn.trustindex.io/loader.js?8e4f0094742191992616bdb1eb7 and the About Us page loads https://birdeye.com/embed/v7/170734503716585/11/987654321301115183, likely used for reputation management and review widgets.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager, Simpli.fi, and TVSquared (unconfirmed product names from script and host references)",
      "purpose": "Marketing analytics, programmatic ad tracking, and broadcast attribution",
      "evidence": {
        "statement": "Site pages load scripts from googletagmanager.com and tag.simpli.fi and reference collector-44216.us.tvsquared.com, suggesting paid digital and broadcast advertising tracking.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "WordPress with Astra and Elementor (unconfirmed product names from asset paths)",
      "purpose": "Website content management system, theme, and page builder",
      "evidence": {
        "statement": "Page script sources under /wp-content/themes/astra/, /wp-content/plugins/elementor/, and /wp-content/plugins/elementor-pro/ indicate a WordPress website built with Astra and Elementor.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The website uses lead capture forms on the homepage and contact page that obtain SMS marketing consent from prospects.",
      "label": "fact",
      "sourceUrl": "https://www.idahoroofingcontractors.com/",
      "quote": "By submitting, you authorize Idaho Roofing Contractors to send text messages with offers and other information."
    },
    {
      "statement": "The Privacy Policy states that contact form submissions are stored in their system and may be sent to third-party vendors.",
      "label": "fact",
      "sourceUrl": "https://www.idahoroofingcontractors.com/privacy-policy/",
      "quote": "If you submit a contact form on our site, the information related to the submission will be stored in our system"
    },
    {
      "statement": "The Contact Us page states that inbound callers speak directly with a local roofing professional rather than a call center.",
      "label": "fact",
      "sourceUrl": "https://www.idahoroofingcontractors.com/contact-us/",
      "quote": "When you reach out, you’ll speak with a local roofing professional — not a call center."
    },
    {
      "statement": "The presence of ad-tracking hosts (tag.simpli.fi, googletagmanager.com, collector-44216.us.tvsquared.com) alongside leads.acculynx.com and app.roofle.com suggests the company actively pays for leads and already uses roofing-specific software to capture and quote them.",
      "label": "hypothesis",
      "sourceUrl": null,
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Inbound phone calls outside normal business hours or during peak storm surges could go to voicemail if handled strictly by in-house roofing professionals without a call center.",
      "label": "hypothesis",
      "basis": "The Contact Us page states that callers speak with a local roofing professional rather than a call center, though actual call-handling performance and missed-call rates cannot be verified from the public site."
    },
    {
      "problem": "Marketing spend across multiple ad channels (Google Ads, programmatic, and broadcast) may require manual consolidation to track cost per booked job.",
      "label": "hypothesis",
      "basis": "Multiple tracking tags appear on the website (googletagmanager.com, tag.simpli.fi, collector-44216.us.tvsquared.com), though internal reporting workflows are not publicly visible."
    }
  ],
  "existingSolutions": [
    {
      "solution": "AccuLynx CRM and lead intake (referenced via leads.acculynx.com)",
      "addresses": "Capturing web leads directly into roofing field-service and job management software and automating follow-up communications.",
      "alreadyOwned": true
    },
    {
      "solution": "Roofle Roof Quote PRO (referenced via app.roofle.com/roof-quote-pro-widget.js)",
      "addresses": "Instant online roof estimation and automated lead capture for homeowners.",
      "alreadyOwned": true
    },
    {
      "solution": "Birdeye (referenced via birdeye.com script)",
      "addresses": "Automated customer messaging, review generation, and reputation management.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Idaho Roofing Contractors is a roofing contractor outside ForgeX's target segment (HVAC, plumbing, and electrical contractors) and already shows technical evidence of specialized roofing lead-capture and quoting software."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended for this company."
  },
  "humanReview": [
    "No ForgeX automation is recommended; in general, any contractor-facing estimating or warranty registration workflow would require human inspection verification."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Pursuing a roofing contractor outside ForgeX's core HVAC, plumbing, and electrical segment would require integrating with roofing-specific software (such as AccuLynx and Roofle) rather than standard MEP field-service platforms."
    },
    {
      "type": "compliance",
      "description": "Any automated SMS follow-up on web forms must comply with TCPA consent and opt-out rules as referenced in the site's form disclaimer."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "Although the FAQ page states an illustrative Boise market range of $10,000 to $15,000 for residential roof replacements, commercial value for a ForgeX engagement is not calculated because the company is outside ForgeX's segment and no ForgeX service is recommended."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Managing Member",
      "General Manager",
      "Sales or Operations Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.idahoroofingcontractors.com/contact-us/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How are web form submissions and instant roof quotes currently routed into your CRM and assigned to sales estimators?",
      "Who handles inbound phone inquiries when estimators are on roofs or after normal business hours?",
      "How do you currently reconcile ad spend from Google, programmatic, and TV campaigns against closed roofing jobs?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.idahoroofingcontractors.com/",
        "usedFor": "Company identity, Meridian address, founding year (2001), roofing services, review count, Owens Corning certification, license number RCE-5471, and technical script/host references."
      },
      {
        "url": "https://www.idahoroofingcontractors.com/about-us/",
        "usedFor": "Company background, family-operated history, team department structure, and Birdeye script reference."
      },
      {
        "url": "https://www.idahoroofingcontractors.com/contact-us/",
        "usedFor": "Primary business phone number, contact form details, and local non-call-center phone handling statement."
      },
      {
        "url": "https://www.idahoroofingcontractors.com/services/",
        "usedFor": "Verification of principal business activities (exclusively roofing) and licensing/insurance disclosures."
      },
      {
        "url": "https://www.idahoroofingcontractors.com/faq/",
        "usedFor": "Published residential roof replacement price range ($10,000 to $15,000), inspection process, and license confirmation."
      },
      {
        "url": "https://www.idahoroofingcontractors.com/privacy-policy/",
        "usedFor": "Data handling practices for contact forms and confirmation of Google Ads usage."
      },
      {
        "url": "https://www.idahoroofingcontractors.com/terms/",
        "usedFor": "Verification of legal entity name (Idaho Roofing Contractors LLC) and contract/estimate terms."
      }
    ],
    "limitations": [
      "Exact employee headcount is not stated on the public website.",
      "No individual owners, executives, or managers are named in the text of the About Us page or other pages read.",
      "No business email address is published in the text or mailto links of the pages read.",
      "Internal software configurations and actual lead-response times cannot be verified from public pages alone."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "ForgeX's target segment is owner-led HVAC, plumbing, and electrical contractors. Idaho Roofing Contractors LLC is exclusively a residential and commercial roofing contractor and does not provide HVAC, plumbing, or electrical services. Additionally, technical references on the website (leads.acculynx.com, app.roofle.com, birdeye.com) indicate the company already uses specialized roofing CRM, instant quoting, and reputation management tools."
  }
}
